import json
from glob import glob
import os
def task_func(directory, string):
    def search_in_data(data, target):
        if isinstance(data, str):
            return target in data
        elif isinstance(data, dict):
            return any(search_in_data(v, target) for v in data.values())
        elif isinstance(data, list):
            return any(search_in_data(item, target) for item in data)
        return False

    results = []
    search_path = os.path.join(directory, '**', '*.json')
    for file_path in glob(search_path, recursive=True):
        try:
            with open(file_path, 'r') as f:
                data = json.load(f)
                if search_in_data(data, string):
                    results.append(file_path)
        except (json.JSONDecodeError, IOError):
            continue
    return results

