import json
import re
import pandas as pd
def task_func(json_str):
    if not json_str:
        return pd.DataFrame()
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return pd.DataFrame()

    if not isinstance(data, dict):
        return pd.DataFrame()

    def process_val(val):
        if isinstance(val, (int, float)):
            return float(val * 2)
        elif isinstance(val, list):
            return [float(x * 2) if isinstance(x, (int, float)) else x for x in val]
        elif isinstance(val, str):
            return re.sub(r"[-+]?\d*\.\d+|\d+", lambda m: str(float(m.group()) * 2), val)
        return val

    processed_data = {k: process_val(v) for k, v in data.items()}

    try:
        df = pd.DataFrame([processed_data])
        return df
    except Exception:
        return pd.DataFrame()

